// ---- the check --------------------------------------------------------------------------

/** Parent words (the du'a router's list, src/data/duas/parent-grief.ts, lives here). */
export const PARENT_WORDS: readonly string[] = [
  'mother', 'mothers', 'mum', 'mums', 'mom', 'moms',
  'father', 'fathers', 'dad', 'dads',
  'parent', 'parents',
]
/** Parent words beyond the du'a router's list: step-parents and common short forms. */
export const MORE_PARENT_WORDS: readonly string[] = [
  'mama', 'mamma', 'papa', 'abba', 'ammi', 'ami', 'baba',
  'stepdad', 'stepdads', 'stepfather', 'stepfathers', 'stepmum', 'stepmums', 'stepmom', 'stepmoms', 'stepmother', 'stepmothers',
  'stepparent', 'stepparents',
]
export const PARENT_HARM_PARENTS: ReadonlySet<string> = new Set([...PARENT_WORDS, ...MORE_PARENT_WORDS])

/** Harm words, matched as whole words after the same normalising. */
export const HARM_WORDS: ReadonlySet<string> = new Set([
  'hurt', 'hurts', 'hurting', 'hit', 'hits', 'hitting', 'beat', 'beats', 'beating', 'beaten',
  'slap', 'slaps', 'slapped', 'slapping', 'punch', 'punches', 'punched', 'kick', 'kicks', 'kicked',
  'abuse', 'abuses', 'abused', 'abusing', 'abusive', 'cruel', 'cruelty', 'violent', 'violence',
  'harm', 'harms', 'harmed', 'harming', 'threaten', 'threatens', 'threatened', 'threatening',
  'scream', 'screams', 'screaming', 'yell', 'yells', 'yelling', 'shout', 'shouts', 'shouting',
  'insult', 'insults', 'insulted', 'humiliate', 'humiliates', 'humiliated', 'bully', 'bullies', 'bullied',
  'control', 'controls', 'controlling', 'manipulate', 'manipulates', 'manipulative', 'neglect', 'neglects', 'neglected',
  'toxic', 'hate', 'hates', 'scared', 'afraid', 'terrified', 'unsafe', 'locks', 'locked', 'starve', 'starves',
  // WO#502 (Architect, 25 Oct)
  'choke', 'chokes', 'burn', 'burns', 'lock',
])
/** Multi-word harm phrases ("treat me badly"). */
export const HARM_PHRASES: readonly string[][] = [
  ['treat', 'me', 'badly'], ['treats', 'me', 'badly'], ['treated', 'me', 'badly'],
  ['kicked', 'me', 'out'], ['kick', 'me', 'out'], ['throw', 'me', 'out'], ['threw', 'me', 'out'],
]

/** The words of a message: lower case, apostrophes dropped, split on anything that is not a letter or digit. */
export function queryWords(text: string): string[] {
  return text
    .toLowerCase()
    .replace(/['’]/g, '')
    .replace(/[^\p{L}\p{N}]+/gu, ' ')
    .trim()
    .split(' ')
    .filter(Boolean)
}

/** True when the message names a parent and a harm. */
export function mentionsParentHarm(text: string): boolean {
  const w = queryWords(text)
  if (!w.some((x) => PARENT_HARM_PARENTS.has(x))) return false
  if (w.some((x) => HARM_WORDS.has(x))) return true
  const joined = ` ${w.join(' ')} `
  return HARM_PHRASES.some((p) => joined.includes(` ${p.join(' ')} `))
}

// ---- the withheld list --------------------------------------------------------------------

/** The verses withheld on parent harm, in mushaf order. */
export const PARENT_HARM_WITHHELD_VERSES: readonly { surah: number; ayah: number }[] = [
  { surah: 17, ayah: 23 },
  { surah: 17, ayah: 24 },
  { surah: 31, ayah: 14 },
  { surah: 31, ayah: 15 },
  { surah: 46, ayah: 15 },
  { surah: 66, ayah: 6 },
]

/** True when the inclusive range surah:from-to covers a withheld verse. */
export function withheldRange(surah: number, from: number, to: number): boolean {
  return PARENT_HARM_WITHHELD_VERSES.some((w) => w.surah === surah && from <= w.ayah && w.ayah <= to)
}

/** True when a reference ("Quran 17:24", "Surah Al-Isra 17:23-24", "(66:6)", "46:15") includes a withheld verse. */
export function citesWithheldVerse(reference: string | undefined | null): boolean {
  if (!reference) return false
  for (const m of reference.matchAll(/(\d{1,3}):(\d{1,3})(?:\s*[-–]\s*(\d{1,3}))?/g)) {
    if (withheldRange(+m[1], +m[2], +(m[3] ?? m[2]))) return true
  }
  return false
}

/**
 * Strings withheld by id (Gem 3, WO#503-B item 2). A mood-content entry is named
 * by its mood, sub-category, kind and key (the verse reference or the du'a source,
 * exactly as shipped); a life-situation field by the situation id and the field
 * path. The record is docs/wo503-architect.md section 5; the resolution of each
 * path to exactly one shipped string is docs/wo503b-data/withheld-strings.json.
 */
export type WithheldString =
  | { kind: 'mood-message'; mood: string; sub: string }
  | { kind: 'mood-verse'; mood: string; sub: string; key: string }
  | { kind: 'mood-dua'; mood: string; sub: string; key: string }
  | { kind: 'situation-field'; situation: string; path: string }
export const PARENT_HARM_WITHHELD_STRINGS: readonly WithheldString[] = [
  { kind: 'mood-dua', mood: 'lonely', sub: 'relationship_related', key: 'Abu Dawud 969 (Part of the salaam)' },
  { kind: 'mood-dua', mood: 'lonely', sub: 'social_related', key: 'Abu Dawud 969' },
  { kind: 'mood-verse', mood: 'sad', sub: 'parenting_related', key: 'Surah Al-Ankabut 29:8' },
  { kind: 'mood-message', mood: 'angry', sub: 'family_related' },
  { kind: 'mood-dua', mood: 'angry', sub: 'family_related', key: 'Quran 14:41' },
  { kind: 'situation-field', situation: 'marriage', path: 'verses[4].translation' },
  { kind: 'situation-field', situation: 'parenting', path: 'verses[4].translation' },
  { kind: 'situation-field', situation: 'family-conflict', path: 'verses[0].translation' },
  { kind: 'situation-field', situation: 'family-conflict', path: 'verses[1].translation' },
  { kind: 'situation-field', situation: 'family-conflict', path: 'verses[1].reflection' },
  { kind: 'situation-field', situation: 'family-conflict', path: 'verses[2].reflection' },
]

/** True when a mood-content item (a message, or a verse by reference, or a du'a by source) is withheld by id. */
export function isWithheldMoodItem(kind: 'mood-message' | 'mood-verse' | 'mood-dua', mood: string, sub: string | null | undefined, key?: string | null): boolean {
  if (!sub) return false
  return PARENT_HARM_WITHHELD_STRINGS.some((w) => w.kind === kind && w.mood === mood && w.sub === sub && (w.kind === 'mood-message' || w.key === key))
}

/** True when a life situation carries a field withheld by id. */
export function situationHasWithheldField(situationId: string): boolean {
  return PARENT_HARM_WITHHELD_STRINGS.some((w) => w.kind === 'situation-field' && w.situation === situationId)
}
